class Solution {
  String findTheDifference(String s, String t) {
    // Create a list to store the characters of string s and their frequencies.
    List<int> charFrequency = [0] * 26;

    // Iterate through each character in string s and increment its frequency count.
    for (int i = 0; i < s.length; i++) {
      int index = s.codeUnitAt(i) - 'a'.codeUnitAt(0);
      charFrequency[index]++;
    }

    // Initialize result with an empty string.
    String result = "";

    // Iterate through each character in string t:
    for (int j = 0; j < t.length; j++) {
      int index = t.codeUnitAt(j) - 'a'.codeUnitAt(0);

      if (charFrequency[index] > 0) {
        // If the character is already present in string s, decrement its frequency count.
        charFrequency[index]--;
      } else {
        // Otherwise, we found the extra character which causes the difference between strings s and t.
        result += t[j];
        break;
      }
    }

    return result;
  }
}

