String solve(List<String> lines) {
  Map<int, Set<int>> graph = {};
  for (int i = 0; i < lines.length - 1; ++i) {
    final parts = lines[i].split(':');
    int nodeIndex = int.parse(parts[0]);
    graph.putIfAbsent(nodeIndex, () => {} as Set<int>).addAll(
      parts[1].split(',').map((edge) => int.parse(edge.trim())).toSet(),
    );
  }

  // Compute distances from node 1 to all other nodes using BFS.
  final visited = <int>[];
  final queue = [1];
  while (queue.isNotEmpty) {
    final currNode = queue.removeAt(0);
    if (!visited.contains(currNode)) {
      visited.add(currNode);
      final neighbors = graph[currNode] ?? {};
      queue.addAll(neighbors.toList());
    }
  }

  return "${lines.last}\n${visited.join('\n')}";
}

