class RBTree {
  Node root;
  bool isRed;

  RBTree() : root = null, isRed = false;

  void insertNode(int data) {
    if (root == null) {
      root = Node(data);
      return;
    } else {
      _insertNode(root, data);
    }
  }

  void _insertNode(Node node, int data) {
    if (data < node.value) {
      if (node.left != null) {
        _insertNode(node.left!, data);
      } else {
        node.left = Node(data);
      }
    } else {
      if (node.right != null) {
        _insertNode(node.right!, data);
      } else {
        node.right = Node(data);
      }
    }
  }

  List<int> searchNode(int key) {
    var result = [];
    _searchNode(root, key, result);
    return result;
  }

  void _searchNode(Node node, int key, List<int> result) {
    if (node == null) return;
    if (key < node.value) {
      _searchNode(node.left, key, result);
    } else if (key > node.value) {
      _searchNode(node.right, key, result);
    } else {
      result.add(key);
    }
  }

  void printInorderTraversal() {
    var list = inorder();
    for (var item in list) {
      stdout.write(item + " ");
    }
    stdout.writeln("");
  }

  List<int> inorder() {
    var list = <int>[];
    _inorder(root, list);
    return list;
  }

  void _inorder(Node node, List<int> list) {
    if (node == null) return;
    _inorder(node.left, list);
    list.add(node.value);
    _inorder(node.right, list);
  }

  List<int> preorder() {
    var list = <int>[];
    _preorder(root, list);
    return list;
  }

  void _preorder(Node node, List<int> list) {
    if (node == null) return;
    list.add(node.value);
    _preorder(node.left, list);
    _preorder(node.right, list);
  }

  List<int> postorder() {
    var list = <int>[];
    _postorder(root, list);
    return list;
  }

  void _postorder(Node node, List<int> list) {
    if (node == null) return;
    _postorder(node.left, list);
    _postorder(node.right, list);
    list.add(node.value);
  }

  String toString() {
    return "Root: $root";
  }
}

