int bronKerbosch(Set<int> R, Set<int> P, Set<int> X) {
  if (P.isEmpty && X.isEmpty) return R;

  final U = <Set<int>>[];

  for (final v in P.toList()) {
    final Z = <int>[];

    for (final w in P - X - {v}) {
      if (!R.contains(w)) Z.add(v);
    }

    U.addAll(Z.map((x) => {x}));
  }

  int max = -1;
  Set<int> bestR = {};

  for (final u in U) {
    final newR = R.union(u);
    final newX = X.intersection(U);

    int size = bronKerbosch(newR, P.difference({u}), newX).length;

    if (size > max) {
      max = size;
      bestR = newR;
    }
  }

  return bestR;
}

