    } else if (t > dx * dx + dy * dy) {
      return (point.x - lineP2.x).pow(2) + (point.y - lineP2.y).pow(2);
    } else {
      double x = lineP1.x + t * ux;
      double y = lineP1.y + t * uy;

      return (point.x - x).pow(2) + (point.y - y).pow(2);
    }
  }
