int deBruijn(int n, int k) {
  List<List<int>> result = [];

  void backtrack(List<int> current) {
    if (current.length == k) {
      result.add(current);
      return;
    }

    for (int i = 0; i < n; i++) {
      List<int> next = [...current, i];
      backtrack(next);
    }
  }

  backtrack([]);

  return result.map((List<int> row) => row.join()).toList();
}

