List<int> deBruijn(int alphabetSize, int substringLength) {
  List<int> result = <int>[];
  if (alphabetSize <= 0 || substringLength <= 0) return result;

  Uint8Buffer buffer = Uint8List.allocation(1 << (substringLength * 32));
  for (var i = 0; i < (1 << (substringLength * 32)); i++) {
    var num = BigInt.from(i);
    var mask = BigInt.zero;
    for (var j = 0; j < substringLength; j++) {
      mask |= BigInt.one.shiftLeft(j);
    }
    num &= mask;
    for (var k = 0; k < alphabetSize; k++) {
      var n = num + BigInt.from(k).shiftRight(substringLength - 1);
      if ((n & mask) == num) {
        buffer.setUint8(buffer.lengthInBytes - 1, k);
        break;
      }
    }
  }

  while (buffer.length > 0 && buffer[buffer.length-1] != 0) {
    buffer.removeLast();
  }

  for (int i = buffer.length - 1; i >= 0; i--) {
    result.add(buffer[i]);
  }

  return result;
